const upsertBrandProfile = `-- name: UpsertBrandProfile :one
INSERT INTO brand_profiles (org_id, website, sells, audience, proof, voice)
VALUES (?, ?, ?, ?, ?, ?)
ON CONFLICT (org_id) DO UPDATE SET
    website = excluded.website, sells = excluded.sells, audience = excluded.audience,
    proof = excluded.proof, voice = excluded.voice, updated_at = strftime('%Y-%m-%d %H:%M:%S', 'now')
RETURNING org_id, website, sells, audience, proof, voice, updated_at
`

type UpsertBrandProfileParams struct {
	OrgID    string `json:"org_id"`
	Website  string `json:"website"`
	Sells    string `json:"sells"`
	Audience string `json:"audience"`
	Proof    string `json:"proof"`
	Voice    string `json:"voice"`
}

func (q *Queries) UpsertBrandProfile(ctx context.Context, arg UpsertBrandProfileParams) (BrandProfile, error) {
	row := q.db.QueryRowContext(ctx, upsertBrandProfile,
		arg.OrgID,
		arg.Website,
		arg.Sells,
		arg.Audience,
		arg.Proof,
		arg.Voice,
	)
	var i BrandProfile
	err := row.Scan(
		&i.OrgID,
		&i.Website,
		&i.Sells,
		&i.Audience,
		&i.Proof,
		&i.Voice,
		&i.UpdatedAt,
	)
	return i, err
}
